output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "Customers must take the available entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Customers are prohibited from picking up shelf items unless they are currently pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "pushing_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are prohibited from carrying groceries by hand rather than using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_nw_bay",
    "text": "After taking a cart, customers must return it to the north-west cart bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "northwest_cart_bay": "at(0,1)",
        "cart_parked_in_nw_bay": "cartAt(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        },
        "return_cart_to_nw_bay": {
          "pre": {
            "and": [
              "northwest_cart_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_nw_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_nw_bay"
    }
  },
  {
    "id": "leave_cart_only_at_nw_bay",
    "text": "Customers may put down a cart only at the designated north-west cart-return bay.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "northwest_cart_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "Customers are prohibited from exiting until the cart is parked in the north-west return bay and they are no longer pushing it.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_nw_bay": "cartAt(0,1)",
        "pushing_cart": "hasCart",
        "ready_to_exit_without_cart": {
          "and": [
            "cart_parked_in_nw_bay",
            {
              "not": "pushing_cart"
            }
          ]
        }
      },
      "events": {
        "bad_exit_with_unreturned_cart": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "ready_to_exit_without_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "bad_exit_with_unreturned_cart"
    }
  },
  {
    "id": "must_pick_cart_when_at_station",
    "text": "When standing on the entrance cart station with the cart present, customers must not move away or do anything other than pick up the cart.",
    "abstraction": {
      "state_properties": {
        "standing_at_available_entrance_cart": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "ignore_available_entrance_cart": {
          "pre": {
            "and": [
              "standing_at_available_entrance_cart",
              {
                "not": "PICKUP_CART"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "ignore_available_entrance_cart"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart has been returned to the north-west bay, customers are prohibited from performing further shopping interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_session_closed": "cartAt(0,1)"
      },
      "events": {
        "post_return_shopping_interaction": {
          "pre": {
            "and": [
              "cart_session_closed",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_shopping_interaction"
    }
  }
]
